    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary mt-3" @onclick="ProceedToStep2">
            Check Availability
        </button>
    }

    @* STEP 2: Appointment Details *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                    @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey("Doctor"))
                {
                    <div class="validation-message">@serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                    @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>
        </fieldset>

        <button type="submit" class="btn btn-success mt-3">Book Appointment</button>
        <button type="button" class="btn btn-secondary mt-3 ms-2" @onclick="GoBackToStep1">Back</button>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool submitted;
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private EditContext? editContext;

    private async Task ProceedToStep2()
    {
        serverErrors.Clear();

        // Validate step 1 fields manually
        editContext = new EditContext(Model);
        var validationMessages = new ValidationMessageStore(editContext);

        bool step1Valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Email) || !IsValidEmail(Model.Email))
        {
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            step1Valid = false;
        }

        if (!step1Valid)
        {
            // Trigger DataAnnotations validation by notifying
            editContext.Validate();
            return;
        }

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private void GoBackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
    }

    private async Task HandleSubmit()
    {
        serverErrors.Clear();
        submitted = false;

        // Run server-side validation
        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor ?? "",
            Model.TimeSlot ?? "");

        if (errors.Count > 0)
        {
            serverErrors = errors;
            return;
        }

        submitted = true;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}
"}

