    private EditContext editContext = default!;
    private ValidationMessageStore validationMessageStore = default!;
    private bool showStep2;
    private bool submitted;
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
        validationMessageStore = new ValidationMessageStore(editContext);
        editContext.OnValidationRequested += (_, _) => validationMessageStore.Clear();
        editContext.OnFieldChanged += (_, e) =>
        {
            validationMessageStore.Clear(e.FieldIdentifier);
            // Clear server errors for the changed field
            serverErrors.Remove(e.FieldIdentifier.FieldName);
        };
    }

    private async Task ProceedToStep2()
    {
        serverErrors.Clear();
        validationMessageStore.Clear();

        // Validate only step 1 fields
        bool step1Valid = true;
        var fields = new[] { nameof(Model.PatientName), nameof(Model.Email), nameof(Model.Phone), nameof(Model.InsuranceProvider) };

        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new ValidationContext(Model);

        foreach (var field in fields)
        {
            var prop = typeof(AppointmentModel).GetProperty(field)!;
            var value = prop.GetValue(Model);
            var fieldResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
            var fieldContext = new ValidationContext(Model) { MemberName = field };
            if (!Validator.TryValidateProperty(value, fieldContext, fieldResults))
            {
                step1Valid = false;
                var fieldIdentifier = editContext.Field(field);
                foreach (var result in fieldResults)
                {
                    validationMessageStore.Add(fieldIdentifier, result.ErrorMessage!);
                }
            }
        }

        editContext.NotifyValidationStateChanged();

        if (!step1Valid)
        {
            return;
        }

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
